import { rename } from "node:fs/promises";

type Status = "open" | "done";

interface Task {
  id: number;
  title: string;
  status: Status;
  tags: string[];
  due?: string;
  createdAt: string;
  completedAt?: string;
}

interface Database {
  version: 1;
  nextId: number;
  tasks: Task[];
}

class CliError extends Error {}

const databasePath = process.env.TASKBOARD_FILE || ".taskboard.json";

function fail(message: string): never {
  throw new CliError(message);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function validDate(value: string): boolean {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) return false;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(Date.UTC(year, month - 1, day));
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

function normalizeTag(tag: string): string {
  return tag.trim().toLowerCase();
}

function normalizeTags(value: string): string[] {
  const result: string[] = [];
  const seen = new Set<string>();
  for (const raw of value.split(",")) {
    const tag = normalizeTag(raw);
    if (!tag || seen.has(tag)) continue;
    seen.add(tag);
    result.push(tag);
  }
  return result;
}

function validateTask(value: unknown, index: number): asserts value is Task {
  if (!isRecord(value)) fail(`malformed database: task ${index} is not an object`);
  if (!Number.isSafeInteger(value.id) || (value.id as number) < 1)
    fail(`malformed database: invalid task id at index ${index}`);
  if (typeof value.title !== "string" || value.title.trim() === "")
    fail(`malformed database: invalid title for task ${value.id}`);
  if (value.status !== "open" && value.status !== "done")
    fail(`malformed database: invalid status for task ${value.id}`);
  if (!Array.isArray(value.tags) || value.tags.some((tag) => typeof tag !== "string"))
    fail(`malformed database: invalid tags for task ${value.id}`);
  const tags = value.tags as string[];
  if (tags.some((tag) => tag === "" || normalizeTag(tag) !== tag) || new Set(tags).size !== tags.length)
    fail(`malformed database: non-normalized tags for task ${value.id}`);
  if (value.due !== undefined && (typeof value.due !== "string" || !validDate(value.due)))
    fail(`malformed database: invalid due date for task ${value.id}`);
  if (typeof value.createdAt !== "string" || Number.isNaN(Date.parse(value.createdAt)))
    fail(`malformed database: invalid createdAt for task ${value.id}`);
  if (value.completedAt !== undefined &&
      (typeof value.completedAt !== "string" || Number.isNaN(Date.parse(value.completedAt))))
    fail(`malformed database: invalid completedAt for task ${value.id}`);
  if (value.status === "done" && value.completedAt === undefined)
    fail(`malformed database: done task ${value.id} has no completedAt`);
  if (value.status === "open" && value.completedAt !== undefined)
    fail(`malformed database: open task ${value.id} has completedAt`);
}

async function loadDatabase(): Promise<Database> {
  let text: string;
  try {
    text = await Bun.file(databasePath).text();
  } catch (error) {
    const code = isRecord(error) ? error.code : undefined;
    if (code === "ENOENT") return { version: 1, nextId: 1, tasks: [] };
    fail(`cannot read database: ${error instanceof Error ? error.message : String(error)}`);
  }

  let value: unknown;
  try {
    value = JSON.parse(text);
  } catch {
    fail("malformed database: invalid JSON");
  }
  if (!isRecord(value) || value.version !== 1 ||
      !Number.isSafeInteger(value.nextId) || (value.nextId as number) < 1 ||
      !Array.isArray(value.tasks)) {
    fail("malformed database: invalid document structure");
  }
  const ids = new Set<number>();
  for (let index = 0; index < value.tasks.length; index++) {
    validateTask(value.tasks[index], index);
    const id = value.tasks[index].id;
    if (ids.has(id)) fail(`malformed database: duplicate task id ${id}`);
    ids.add(id);
  }
  const maximumId = value.tasks.reduce((maximum, task) => Math.max(maximum, task.id), 0);
  if ((value.nextId as number) <= maximumId)
    fail("malformed database: nextId does not exceed existing ids");
  return value as unknown as Database;
}

async function saveDatabase(database: Database): Promise<void> {
  const slash = databasePath.lastIndexOf("/");
  const directory = slash < 0 ? "." : databasePath.slice(0, slash) || "/";
  const base = slash < 0 ? databasePath : databasePath.slice(slash + 1);
  const temporaryPath = `${directory}/.${base}.${process.pid}.${crypto.randomUUID()}.tmp`;
  try {
    await Bun.write(temporaryPath, `${JSON.stringify(database, null, 2)}\n`);
    await rename(temporaryPath, databasePath);
  } catch (error) {
    try { await Bun.file(temporaryPath).delete(); } catch {}
    fail(`cannot write database: ${error instanceof Error ? error.message : String(error)}`);
  }
}

function parseOptions(args: string[], allowed: Set<string>): Map<string, string> {
  const options = new Map<string, string>();
  for (let index = 0; index < args.length; index++) {
    const flag = args[index];
    if (!flag.startsWith("--")) fail(`unexpected argument: ${flag}`);
    if (!allowed.has(flag)) fail(`unknown flag: ${flag}`);
    if (options.has(flag)) fail(`duplicate flag: ${flag}`);
    const value = args[++index];
    if (value === undefined) fail(`missing value for ${flag}`);
    options.set(flag, value);
  }
  return options;
}

function parseId(value: string | undefined): number {
  if (value === undefined || !/^[1-9]\d*$/.test(value)) fail("ID must be a positive integer");
  const id = Number(value);
  if (!Number.isSafeInteger(id)) fail("ID must be a positive safe integer");
  return id;
}

function localToday(): string {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, "0");
  const day = String(now.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

async function execute(args: string[]): Promise<unknown> {
  const [command, ...rest] = args;
  if (!command) fail("missing command");

  if (command === "add") {
    const options = parseOptions(rest, new Set(["--title", "--tags", "--due"]));
    const title = options.get("--title");
    if (title === undefined) fail("missing required flag: --title");
    if (title.trim() === "") fail("title must not be empty");
    const due = options.get("--due");
    if (due !== undefined && !validDate(due)) fail("due date must be a valid YYYY-MM-DD date");
    const database = await loadDatabase();
    const task: Task = {
      id: database.nextId++,
      title,
      status: "open",
      tags: options.has("--tags") ? normalizeTags(options.get("--tags")!) : [],
      createdAt: new Date().toISOString(),
      ...(due === undefined ? {} : { due }),
    };
    database.tasks.push(task);
    await saveDatabase(database);
    return task;
  }

  if (command === "list") {
    const options = parseOptions(rest, new Set(["--status", "--tag", "--overdue"]));
    const status = options.get("--status");
    if (status !== undefined && status !== "open" && status !== "done")
      fail("status must be open or done");
    const tag = options.has("--tag") ? normalizeTag(options.get("--tag")!) : undefined;
    if (tag === "") fail("tag must not be empty");
    const overdue = options.get("--overdue");
    if (overdue !== undefined && !validDate(overdue))
      fail("overdue date must be a valid YYYY-MM-DD date");
    const database = await loadDatabase();
    return database.tasks
      .filter((task) => status === undefined || task.status === status)
      .filter((task) => tag === undefined || task.tags.includes(tag))
      .filter((task) => overdue === undefined ||
        (task.status === "open" && task.due !== undefined && task.due < overdue))
      .sort((left, right) => left.id - right.id);
  }

  if (command === "done") {
    if (rest.length !== 1) fail("usage: done ID");
    const id = parseId(rest[0]);
    const database = await loadDatabase();
    const task = database.tasks.find((candidate) => candidate.id === id);
    if (!task) fail(`task ${id} not found`);
    if (task.status === "open") {
      task.status = "done";
      task.completedAt = new Date().toISOString();
      await saveDatabase(database);
    }
    return task;
  }

  if (command === "delete") {
    if (rest.length !== 1) fail("usage: delete ID");
    const id = parseId(rest[0]);
    const database = await loadDatabase();
    const index = database.tasks.findIndex((candidate) => candidate.id === id);
    if (index < 0) fail(`task ${id} not found`);
    const [task] = database.tasks.splice(index, 1);
    await saveDatabase(database);
    return task;
  }

  if (command === "stats") {
    if (rest.length !== 0) fail(`unknown flag or argument: ${rest[0]}`);
    const tasks = (await loadDatabase()).tasks;
    const today = localToday();
    return {
      total: tasks.length,
      open: tasks.filter((task) => task.status === "open").length,
      done: tasks.filter((task) => task.status === "done").length,
      overdue: tasks.filter((task) => task.status === "open" && task.due !== undefined && task.due < today).length,
    };
  }

  fail(`unknown command: ${command}`);
}

