import { afterEach, describe, expect, test } from "bun:test";
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

const cli = join(import.meta.dir, "..", "src", "cli.ts");
const directories: string[] = [];

async function workspace(): Promise<{ directory: string; database: string }> {
  const directory = await mkdtemp(join(tmpdir(), "taskboard-test-"));
  directories.push(directory);
  return { directory, database: join(directory, "tasks.json") };
}

async function run(database: string, args: string[]) {
  const process = Bun.spawn(["bun", "run", cli, ...args], {
    env: { ...Bun.env, TASKBOARD_FILE: database },
    stdout: "pipe",
    stderr: "pipe",
  });
  const [stdout, stderr, exitCode] = await Promise.all([
    new Response(process.stdout).text(),
    new Response(process.stderr).text(),
    process.exited,
  ]);
  return { stdout, stderr, exitCode, value: JSON.parse(stdout) };
}

afterEach(async () => {
  await Promise.all(directories.splice(0).map((directory) => rm(directory, { recursive: true, force: true })));
});

describe("taskboard CLI", () => {
  test("persists tasks, normalizes tags, filters, completes, and keeps ids stable", async () => {
    const { database } = await workspace();
    const first = await run(database, ["add", "--title", "First", "--tags", " Work,work, HOME ", "--due", "2000-01-01"]);
    expect(first.exitCode).toBe(0);
    expect(first.value).toMatchObject({ id: 1, status: "open", tags: ["work", "home"], due: "2000-01-01" });

    const second = await run(database, ["add", "--title", "Second"]);
    expect(second.value.id).toBe(2);
    expect((await run(database, ["list", "--tag", "WORK"])).value.map((task: any) => task.id)).toEqual([1]);
    expect((await run(database, ["list", "--overdue", "2000-01-02"])).value.map((task: any) => task.id)).toEqual([1]);

    const done = await run(database, ["done", "1"]);
    const completedAt = done.value.completedAt;
    expect(done.value.status).toBe("done");
    expect((await run(database, ["done", "1"])).value.completedAt).toBe(completedAt);
    expect((await run(database, ["delete", "2"])).value.id).toBe(2);
    expect((await run(database, ["add", "--title", "Third"])).value.id).toBe(3);
  });

  test("stats and AND-combined list filters are correct", async () => {
    const { database } = await workspace();
    await run(database, ["add", "--title", "Late", "--tags", "x", "--due", "2000-01-01"]);
    await run(database, ["add", "--title", "Done", "--tags", "x", "--due", "2000-01-01"]);
    await run(database, ["done", "2"]);
    expect((await run(database, ["list", "--status", "open", "--tag", "x", "--overdue", "2001-01-01"])).value).toHaveLength(1);
    expect((await run(database, ["stats"])).value).toEqual({ total: 2, open: 1, done: 1, overdue: 1 });
  });

  test("rejects invalid input and preserves malformed data", async () => {
    const { database } = await workspace();
    const invalidDate = await run(database, ["add", "--title", "Bad", "--due", "2025-02-30"]);
    expect(invalidDate.exitCode).not.toBe(0);
    expect(invalidDate.stderr).toContain("valid YYYY-MM-DD");
    expect(invalidDate.stdout.trim().split("\n")).toHaveLength(1);

    const original = "{broken json\n";
    await writeFile(database, original);
    const malformed = await run(database, ["add", "--title", "No overwrite"]);
    expect(malformed.exitCode).not.toBe(0);
    expect(malformed.value.error).toContain("malformed database");
    expect(await readFile(database, "utf8")).toBe(original);

    expect((await run(database, ["wat"])).exitCode).not.toBe(0);
  });
});
# Taskboard CLI

A dependency-free TypeScript task manager for [Bun](https://bun.sh/). Tasks are stored in `.taskboard.json` in the current directory, or at the path specified by `TASKBOARD_FILE`. Each invocation emits one JSON value on stdout; errors also use stderr and a non-zero exit status.

```sh
bun run src/cli.ts add --title "Ship release" --tags work,urgent --due 2026-09-10
bun run src/cli.ts list --status open --tag work
bun run src/cli.ts list --overdue 2026-09-11
bun run src/cli.ts done 1
bun run src/cli.ts delete 1
bun run src/cli.ts stats
```

Tags are trimmed, lowercased, and deduplicated. Dates use strict `YYYY-MM-DD` format. Writes use a temporary sibling file followed by an atomic rename, and deleted IDs are never reused.

Run the self-tests with:

```sh
bun test
```
